/// <reference types="vite/client" />
import { DictionaryWordRecord, JLPTLevel, SubtitleLineRecord, SubtitleTokenJSON } from '../../schema/databaseSchema';
import { DICTIONARY_WORDS } from '../mockVideos';
import {
  buildDictionaryByLemma,
  coreSurface,
  lemmaReadingOf,
  linkDictionaryEntry,
} from './link';

/**
 * Real timed captions generated by scripts/fetch-captions.py (one file per youtube_id),
 * with kuromoji tokens added by scripts/tokenize-captions.mjs.
 * Files are lazy-loaded (separate chunks) so they are not part of the main bundle.
 */
export interface RawCaptionToken {
  surface: string;
  lemma?: string; // omitted in the JSON when equal to surface
  reading?: string; // hiragana; omitted when equal to surface or when there is no reading
  romaji: string; // Hepburn; '' when there is no reading
  pos: string; // IPA part of speech, e.g. 名詞
}

export interface CaptionLine {
  start_ms: number;
  end_ms: number;
  ja: string | null;
  th: string | null;
  tokens?: RawCaptionToken[];
}

export interface CaptionFile {
  youtube_id: string;
  source: { ja: string; th: string };
  lines: CaptionLine[];
}

const loaders = import.meta.glob('./*.json') as Record<string, () => Promise<{ default: CaptionFile }>>;

// Cache of load promises keyed by youtube_id. Resolves to undefined when no file exists.
const cache = new Map<string, Promise<CaptionFile | undefined>>();

export const loadRealCaptions = (youtubeId: string): Promise<CaptionFile | undefined> => {
  let p = cache.get(youtubeId);
  if (!p) {
    const loader = loaders[`./${youtubeId}.json`];
    p = loader
      ? loader().then((m) => m.default).catch(() => undefined)
      : Promise.resolve(undefined);
    cache.set(youtubeId, p);
  }
  return p;
};

/**
 * Glossary for words without a dictionary link (src/data/glossary.json, built by scripts/import-glossary.mjs):
 * { "<lemma>|<reading>": "<thai gloss>, <thai gloss>" }. Loaded once. A failed load leaves it empty.
 */
let glossary: Record<string, string> | null = null;
let glossaryPromise: Promise<void> | null = null;
export const loadGlossary = (): Promise<void> => {
  if (!glossaryPromise) {
    glossaryPromise = import('../glossary.json')
      .then((m) => {
        glossary = m.default as Record<string, string>;
      })
      .catch(() => {
        glossary = {};
      });
  }
  return glossaryPromise;
};

/** Caption file together with the glossary, so built lines always see the glossary. */
export const loadCaptionFile = (youtubeId: string): Promise<CaptionFile | undefined> =>
  Promise.all([loadRealCaptions(youtubeId), loadGlossary()]).then(([file]) => file);

/** Word index: { "<youtube_id>": ["<lemma>|<reading>", ...] } of unique content words per clip. */
export type WordIndex = Record<string, string[]>;
let wordIndexPromise: Promise<WordIndex | undefined> | null = null;
export const loadWordIndex = (): Promise<WordIndex | undefined> => {
  if (!wordIndexPromise) {
    wordIndexPromise = import('./word-index.json')
      .then((m) => m.default as WordIndex)
      .catch(() => undefined);
  }
  return wordIndexPromise;
};

// Dictionary entries by lemma (first entry per lemma).
const DICT_BY_LEMMA = buildDictionaryByLemma(DICTIONARY_WORDS);

/** Dictionary entry a word-index key links to (same rule as caption tokens, without the affix check). */
export const linkWordIndexKey = (key: string): DictionaryWordRecord | undefined => {
  const cut = key.indexOf('|');
  return linkDictionaryEntry(DICT_BY_LEMMA, key.slice(0, cut), key.slice(cut + 1));
};

export const glossaryFor = (lemma: string, reading: string): string[] | undefined => {
  const text = glossary?.[`${lemma}|${reading}`];
  if (!text) return undefined;
  const parts = text.split(', ').map((s) => s.trim()).filter(Boolean);
  return parts.length ? parts : undefined;
};

// Thai labels for IPA part-of-speech tags shown on the tap card.
const POS_THAI: Record<string, string> = {
  名詞: 'คำนาม',
  動詞: 'คำกริยา',
  形容詞: 'คำคุณศัพท์',
  副詞: 'คำวิเศษณ์',
  助詞: 'คำช่วย',
  助動詞: 'คำช่วยกริยา',
  連体詞: 'คำขยายนาม',
  接続詞: 'คำเชื่อม',
  感動詞: 'คำอุทาน',
  接頭詞: 'คำนำหน้า',
  記号: 'เครื่องหมาย',
};
const posThai = (pos: string): string => POS_THAI[pos] ?? (pos ? 'อื่นๆ' : '');

// Pure punctuation / symbols (no letters, digits, kana or kanji).
const isPunctuation = (text: string): boolean => !/[\p{L}\p{N}]/u.test(text);
const isKanaOnly = (text: string): boolean => /^[぀-ゟ]+$/.test(text);

// Fallback for lines without kuromoji tokens: split on whitespace and punctuation.
const splitJapanese = (text: string): string[] =>
  text
    .split(/[\s、。！？!?,.「」『』（）()［］\[\]【】…・〜~"'“”‘’:：;；]+/)
    .filter((part) => part.length > 0 && /[\p{L}\p{N}]/u.test(part));

/**
 * Stable id for a caption word that has no dictionary entry: the same word in any clip shares one id, so
 * "จำได้ / กำลังเรียน" follows the word (known %, flashcards). Format: g:<lemma>|<reading> (= word-index key).
 */
export const GLOSS_ID_PREFIX = 'g:';
export const glossWordId = (lemma: string, reading: string): string => `${GLOSS_ID_PREFIX}${lemma}|${reading}`;

const fallbackTokens = (lineId: string, ja: string, jlpt: JLPTLevel): SubtitleTokenJSON[] =>
  splitJapanese(ja).map((surface, tokenIndex) => ({
    surface,
    word_id: `${lineId}-${tokenIndex}`,
    lemma: surface,
    reading_kana: isKanaOnly(surface) ? surface : '',
    romaji: '',
    jlpt_level: jlpt,
    part_of_speech: '',
    contextual_meaning: '',
  }));

/**
 * Caption token -> dictionary entry (src/data/captions/link.ts). Affix tags (接頭詞/接尾) never link.
 */
const linkedEntry = (t: RawCaptionToken, lemma: string, reading: string): DictionaryWordRecord | undefined => {
  if (t.pos.startsWith('接頭') || t.pos.startsWith('接尾')) return undefined;
  return linkDictionaryEntry(DICT_BY_LEMMA, lemma, reading);
};

/**
 * Tokens from kuromoji. Punctuation is not a tap target: it is appended to the previous
 * token's surface (or prefixed to the next one at the start of a line), so the rendered
 * text keeps it.
 */
const tokensFromRaw = (lineId: string, raw: RawCaptionToken[], jlpt: JLPTLevel): SubtitleTokenJSON[] => {
  const folded: RawCaptionToken[] = [];
  let pendingPrefix = '';
  for (const t of raw) {
    if (isPunctuation(t.surface)) {
      if (folded.length > 0) folded[folded.length - 1] = { ...folded[folded.length - 1], surface: folded[folded.length - 1].surface + t.surface };
      else pendingPrefix += t.surface;
      continue;
    }
    folded.push({ ...t, surface: pendingPrefix + t.surface });
    pendingPrefix = '';
  }
  return folded.map((t, tokenIndex) => {
    // Lemma and reading come from the bare word: the folded punctuation is not part of them.
    const { lemma, reading } = lemmaReadingOf(t);
    const romaji = t.romaji ?? '';
    const entry = linkedEntry(t, lemma, reading);
    const base = {
      surface: t.surface,
      lemma,
      part_of_speech: posThai(t.pos),
      contextual_meaning: '',
    };
    if (!entry) {
      // Not linked: a glossary meaning (scripts/export-glossary.mjs) when one exists.
      const gloss = glossaryFor(lemma, reading);
      return {
        ...base,
        word_id: lemma ? glossWordId(lemma, reading) : `${lineId}-${tokenIndex}`,
        reading_kana: reading,
        romaji,
        jlpt_level: jlpt,
        ...(gloss ? { thai_meaning: gloss[0], general_meanings: gloss } : {}),
      };
    }
    // Linked: the card shows the dictionary meaning and level.
    const sameAsLemma = coreSurface(t.surface) === lemma;
    return {
      ...base,
      word_id: entry.id,
      reading_kana: sameAsLemma ? entry.reading_kana : reading,
      romaji: sameAsLemma ? entry.romaji : romaji,
      jlpt_level: entry.jlpt_level,
      thai_meaning: entry.core_meanings[0],
      general_meanings: entry.core_meanings,
    };
  });
};

const buildTokens = (lineId: string, line: CaptionLine, ja: string, jlpt: JLPTLevel): SubtitleTokenJSON[] =>
  line.tokens ? tokensFromRaw(lineId, line.tokens, jlpt) : fallbackTokens(lineId, ja, jlpt);

/**
 * Builds SubtitleLineRecord[] for one video record from its loaded caption file.
 * Ids: `cap-<videoId>-<start_ms>` (suffix -2, -3 on collision within the video).
 * Thai goes only in thai_translation; natural_translation stays empty so it is not shown twice.
 * Lines without Japanese text get raw_text "" and tokens_json [].
 */
export const buildRealSubtitleLines = (
  file: CaptionFile,
  videoId: string,
  jlpt: JLPTLevel
): SubtitleLineRecord[] => {
  const used = new Map<string, number>();
  return file.lines.map((line, i) => {
    const base = `cap-${videoId}-${line.start_ms}`;
    const count = (used.get(base) ?? 0) + 1;
    used.set(base, count);
    const id = count === 1 ? base : `${base}-${count}`;
    const ja = line.ja ?? '';
    const th = line.th ?? undefined;
    return {
      id,
      video_id: videoId,
      line_index: i,
      start_time_ms: line.start_ms,
      end_time_ms: line.end_ms,
      raw_text: ja,
      natural_translation: '',
      thai_translation: th,
      ai_grammar_summary: '',
      tokens_json: ja ? buildTokens(id, line, ja, jlpt) : [],
    };
  });
};
